from pathlib import Path
import json,statistics,re
out=Path('.work/toy-character/dino2')
def read(name):return json.loads((out/name).read_text())
def median(a):return statistics.median(a) if a else 0
def stats(a):return {'min':min(a),'median':median(a),'max':max(a)}
stills={r['name']:r for r in read('stills.json')}
summary=[]
for name in ['desktop','mobile']:
 d=read(name+'-metrics.json');m=d['metrics'];s=m['scenery'];char=stills[name]['character'];charheight=(char['maxY']-char['minY'])/2
 events=s['visibleAppearanceLog'];gaps=[b['time']-a['time'] for a,b in zip(events,events[1:])]
 projections=[{'species':r['species'],'heightRatioMedian':median(r['screenHeights'])/charheight,'screenHeightMedian':median(r['screenHeights']),'fullPercent':r['fullFrames']/r['visibleFrames']*100,'fullFrames':r['fullFrames'],'visibleFrames':r['visibleFrames'],'cameraNearDepthMedianM':median(r['depths'])} for r in m['projections']]
 summary.append({'name':name,'seconds':d['seconds'],'frames':m['frames'],'characterScreenHeight':charheight,'knee':[m['kneeMin'],m['kneeMax']],'thighForward':m['thighForwardMax'],'thighBackward':m['thighBackwardMax'],'supportSlipMm':m['slipMaxMm'],'patchDeformationMm':m['patchSlipMaxMm'],'liftMm':[m['midSwingMinMm'],m['midSwingMaxMm']],'exchanges':s['exchanges'],'rebases':s['rebases'],'repeats':s['repeats'],'visibleAppearances':len(events),'species':list(dict.fromkeys(e['species'] for e in events)),'maxAppearanceGapSeconds':max(gaps),'dinosaurSlipMm':max(a['allContactSlip'] for a in s['animals']),'activeRestarts':sum(a['restarts'] for a in s['animals']),'trees':stats(m['treeCounts']),'objects':stats(m['objectCounts']),'overlapFrames':s['overlapFrames'],'heapStartMiB':d['heapStart']/1048576,'heapEndMiB':d['heapEnd']/1048576,'heapAfterGcMiB':d['heapAfterGc']/1048576,'projections':projections,'errors':d['errors'],'renderer':d['renderer'],'lookSamples':[{'seconds':r['elapsed'],'state':r['snapshot']['state']} for r in d['timeline'] if r['snapshot']['state']!='walk']})
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
assets=read('assets.json');perf=read('performance.json');loading=read('loading.json');verify=(out/'verify.log').read_text();passed=re.findall(r'(\d+) passed[^\n]*',verify)
assert passed and int(passed[-1])==296 and not re.search(r'\d+ failed',verify)
assert all(r['overlapFrames']==0 and len(r['species'])==6 and not r['errors'] for r in summary)
assert all(r['fullFrames']>0 for s in summary for r in s['projections'])
assert all(r['activeRestarts']==0 and r['maxAppearanceGapSeconds']<=20 for r in summary)
lines=['恐竜6体を指定の体長へ拡大し、種類と部位で塗り分けました。植物・岩・地面を同じ縮尺に整え、読み込みの数字と細い線も実装しました。キャラのGLBと歩きのコードは前回の記録とSHA-256が一致しています。コミットはしていません。','', '[静止画](dino2/stills.png) / [実寸の比較図](dino2/scale.png) / [脚の連続写真](dino2/legs-desktop.png) / [読み込みの連続写真](dino2/loading-strip.png)','', '[横長の動画・125秒](dino2/desktop.webm) / [2秒ごとのコマ](dino2/desktop-strip.png) / [縦長の動画・125秒](dino2/mobile.webm) / [2秒ごとのコマ](dino2/mobile-strip.png)','', '恐竜はWalk開始時の鼻先から尾先までの長軸を体長にしました。高さは同じ姿勢のスキニング後の頂点から測っています。長い首を前に伸ばすApatosaurusは、22 mの体長に対して高さが約5.24 mになります。', '', '| 恐竜 | 体長 m | 模型の高さ m | 塗り分け |','| --- | ---: | ---: | --- |']
